    local regionCache = {}
    --- { male = {...}, female = {...}, surnames = {...} } for a region id, or nil.
    function M.region(id)
        local cached = regionCache[id]
        if cached then return cached end
        local p = packedRegions[id]
        if not p then return nil end
        cached = { male = split(p.male), female = split(p.female), surnames = split(p.surnames) }
        regionCache[id] = cached
        return cached
    end
    function M.regionIds()
        local out = {}
        for i, r in ipairs(M.REGION_WEIGHTS) do out[i] = r.id end
        return out
    end
